import path from 'path';
import { desc, eq, inArray, isNull, or, sql } from 'drizzle-orm';
import {
  openDurableDatabase,
  openReadOnlyDatabase,
  transaction,
  closeDatabase,
} from './database';
import { REGISTRY_SCHEMA, REGISTRY_MIGRATIONS } from './migrations';
import { historyRoots, projects, workspaces } from './schema/registry';

type Database = Awaited<ReturnType<typeof openDurableDatabase>>;
const projectFields = {
  id: projects.id,
  workspaceId: workspaces.id,
  name: projects.name,
  projectPath: workspaces.canonicalPath,
  createdAt: projects.createdAt,
  lastOpenedAt: projects.lastOpenedAt,
  storageKind: projects.storageKind,
  sourceFingerprint: projects.sourceFingerprint,
  removedAt: projects.removedAt,
  pinnedAt: projects.pinnedAt,
};
export type ProjectRecord = ReturnType<ProjectRecords['list']>[number];

export class ProjectRecords {
  private constructor(private readonly db: Database) {}

  static async open(root: string): Promise<ProjectRecords> {
    return new ProjectRecords(
      await openDurableDatabase({
        databasePath: path.join(root, 'registry.sqlite'),
        schema: REGISTRY_SCHEMA,
        migrations: REGISTRY_MIGRATIONS,
      }),
    );
  }

  static openReadOnly(root: string): ProjectRecords | null {
    const db = openReadOnlyDatabase({
      databasePath: path.join(root, 'registry.sqlite'),
      schemaVersion: 1 + REGISTRY_MIGRATIONS.length,
    });
    return db ? new ProjectRecords(db) : null;
  }

  transaction<T>(operation: () => T): T {
    return transaction(this.db, operation);
  }

  list() {
    return this.db
      .select(projectFields)
      .from(projects)
      .innerJoin(workspaces, eq(workspaces.projectId, projects.id))
      .where(isNull(projects.removedAt))
      .orderBy(desc(projects.lastOpenedAt), projects.id)
      .all();
  }

  get(projectId: string) {
    return (
      this.db
        .select(projectFields)
        .from(projects)
        .innerJoin(workspaces, eq(workspaces.projectId, projects.id))
        .where(eq(projects.id, projectId))
        .get() ?? null
    );
  }

  findByPath(canonicalPath: string) {
    const owners = this.db
      .select({ projectId: historyRoots.projectId })
      .from(historyRoots)
      .where(eq(historyRoots.canonicalPath, canonicalPath));
    return (
      this.db
        .select(projectFields)
        .from(projects)
        .innerJoin(workspaces, eq(workspaces.projectId, projects.id))
        .where(
          or(
            eq(workspaces.canonicalPath, canonicalPath),
            inArray(projects.id, owners),
          ),
        )
        .get() ?? null
    );
  }

  insert(record: {
    id: string;
    name: string;
    workspaceId: string;
    canonicalPath: string;
    createdAt: string;
  }): void {
    this.db
      .insert(projects)
      .values({
        id: record.id,
        name: record.name,
        createdAt: record.createdAt,
        lastOpenedAt: record.createdAt,
      })
      .run();
    this.db
      .insert(workspaces)
      .values({
        id: record.workspaceId,
        projectId: record.id,
        canonicalPath: record.canonicalPath,
      })
      .run();
  }

  recordOpening(projectId: string, lastOpenedAt: string): void {
    this.db
      .update(projects)
      .set({ lastOpenedAt })
      .where(eq(projects.id, projectId))
      .run();
  }

  rename(projectId: string, name: string): void {
    this.db
      .update(projects)
      .set({ name })
      .where(eq(projects.id, projectId))
      .run();
  }

  setPinned({
    projectId,
    isPinned,
  }: {
    projectId: string;
    isPinned: boolean;
  }): void {
    this.db
      .update(projects)
      .set({
        pinnedAt: isPinned
          ? sql`coalesce(${projects.pinnedAt}, ${new Date().toISOString()})`
          : null,
      })
      .where(eq(projects.id, projectId))
      .run();
  }

  remove(projectId: string): void {
    this.db
      .update(projects)
      .set({
        removedAt: sql`coalesce(${projects.removedAt}, ${new Date().toISOString()})`,
      })
      .where(eq(projects.id, projectId))
      .run();
  }

  restore(projectId: string): void {
    this.db
      .update(projects)
      .set({ removedAt: null })
      .where(eq(projects.id, projectId))
      .run();
  }

  attachHistoryRoot(projectId: string, canonicalPath: string): void {
    this.db
      .insert(historyRoots)
      .values({ projectId, canonicalPath })
      .onConflictDoNothing()
      .run();
  }

  historyRoots(projectId: string): string[] {
    return this.db
      .select({ path: historyRoots.canonicalPath })
      .from(historyRoots)
      .where(eq(historyRoots.projectId, projectId))
      .all()
      .map((row) => row.path);
  }

  relink(projectId: string, canonicalPath: string): void {
    this.db
      .update(workspaces)
      .set({ canonicalPath })
      .where(eq(workspaces.projectId, projectId))
      .run();
  }

  activateBundle(projectId: string, sourceFingerprint: string | null): void {
    this.transaction(() => {
      this.db
        .update(projects)
        .set({ storageKind: 'bundle', sourceFingerprint })
        .where(eq(projects.id, projectId))
        .run();
    });
  }

  close(): void {
    closeDatabase(this.db);
  }
}
